@RestController
@RequestMapping("/api/v1/orders")
public class OrderController {

    @Autowired
    private OrderService orderService;

    // GET /api/v1/orders
    @GetMapping
    public List<Order> getAllOrders() {
        return orderService.findAll();
    }

    // GET /api/v1/orders/42
    @GetMapping("/{id}")
    public ResponseEntity<Order> getOrder(@PathVariable Long id) {
        return orderService.findById(id)
            .map(ResponseEntity::ok)
            .orElse(ResponseEntity.notFound().build());
    }

    // POST /api/v1/orders
    @PostMapping
    public ResponseEntity<Order> createOrder(@RequestBody @Valid CreateOrderRequest req) {
        Order saved = orderService.create(req);
        return ResponseEntity.status(HttpStatus.CREATED).body(saved);
    }

    // PUT /api/v1/orders/42
    @PutMapping("/{id}")
    public Order updateOrder(@PathVariable Long id, @RequestBody @Valid UpdateOrderRequest req) {
        return orderService.update(id, req);
    }

    // DELETE /api/v1/orders/42
    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteOrder(@PathVariable Long id) {
        orderService.delete(id);
        return ResponseEntity.noContent().build();  // 204
    }
}```
